def s_common_templates(*, claims: ClaimCollection):
    structural_rows = body_shared.emit_common_templates_claim_prelude(
        claims=claims,
        plus_only=True,
    )
    kq_rows = body_shared.build_kq_rows(
        claims=claims,
        kq_am2_doc=_KQ_AM2_DOC,
        kq_special_doc=_KQ_SPECIAL_DOC,
    )
    json_kq_plus = cmn.emit_claim_by_id(claims=claims, claim_id="mp.plus.example.kq")
    special_letter_rows = cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.special-letters.set",
    )
    cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.accents.set",
    )
    cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.poetic.set",
    )
    note_row = cmn.emit_claim_by_id(claims=claims, claim_id="mp.both.templates.note")

    plus_accent_rows = cmn.accent_rows_for_templates(_PLUS_ACCENT_TEMPLATES)
    plus_choice_rows = dedicated_rows.with_dualcant_dedicated_page_link(
        cmn.accent_rows_for_templates(_CHOICE_TEMPLATES),
        doc_name=_DUALCANT_DOC,
    )
    poetic_spacing_row = body_shared.poetic_spacing_row(doc_name=_POETIC_SPACING_DOC)

    whitespace_plus_rows = [
        _find_template_row(structural_rows, "מ:ספר חדש"),
        _find_template_row(structural_rows, "מ:רווח בתרי עשר בפסוק הראשון"),
        _find_template_row(structural_rows, "מ:רווח לספר בתהלים בפסוק הראשון"),
    ]
    lack_of_whitespace_rows = [
        _find_template_row(structural_rows, "מ:אין פרשה בתחילת פרק"),
        _find_template_row(structural_rows, "מ:אין פרשה בתחילת פרק בספרי אמ״ת"),
        _find_template_row(structural_rows, "מ:אין רווח של פרשה בתחילת פרשת השבוע"),
    ]
    _emit_claim_payload(
        claims,
        "mp.plus.docs.common-templates.templates-in-plus-survey",
        "Templates listed in mpplus selected-template tables are present in plus survey.",
        kind="enum",
        subject="mp:plus",
        data={"templates": _PLUS_COMMON_TEMPLATES},
    )
    return [
        *body_shared.selected_templates_intro_block(),
        *body_shared.verse_label_templates_block(),
        *body_shared.ketiv_qere_block(kq_rows=kq_rows, json_kq=json_kq_plus),
        author.heading_level_3("Special letter templates"),
        tblh.tmpl_purp_table(
            special_letter_rows
            + [
                [
                    author.hbo("מ:אות-מיוחדת-במילה"),
                    [
                        "Marks a whole word containing a special letter."
                        " (By “special” we mean large, small, or hung.)"
                        " See ",
                        author.anchor_h(
                            "its dedicated page",
                            _AOT_DOC,
                        ),
                        ".",
                    ],
                ]
            ]
        ),
        author.heading_level_3("Punctuation templates"),
        tblh.tmpl_purp_table(plus_accent_rows),
        author.heading_level_3("Choice templates"),
        body_shared.choice_templates_intro_para(),
        tblh.tmpl_purp_table(plus_choice_rows),
        author.heading_level_3("Whitespace templates"),
        tblh.tmpl_purp_table(
            cmn.whitespace_rows_shared() + [poetic_spacing_row] + whitespace_plus_rows
        ),
        author.para(
            "Many editions will choose to skip poetic formatting by treating"
            " ר0–ר4 as simple word spaces."
        ),
        author.heading_level_3("Lack-of-whitespace templates"),
        tblh.tmpl_purp_table(lack_of_whitespace_rows),
        author.heading_level_3("Note template"),
        tblh.tmpl_purp_table([note_row]),
        author.heading_level_3("Documentation templates"),
        tblh.tmpl_purp_table(cmn.other_rows_shared_core(docnote_doc=_DOCNOTE_DOC)),
        body_shared.note_links_param1_explanation_para(),
    ]

